from test_bufftap import test, tests
import test_nearby
setup=test_nearby.setup
test('Animated list switched off moves nothing',setup+"BuffTap.db.nearbyAnimate=false; BuffTap:TrackNearby('nameplate2'); refresh(); BuffTap:UpdateNearbyWindow(); refresh(); BuffTap:UpdateNearbyWindow(); assert(BuffTap.nearbyMotion.moved==0 and BuffTap.nearbyMotion.added==0)")
test('Animated list slides in a new player',setup+"BuffTap.db.nearbyAnimate=true; BuffTap.db.nearbyShowAll=true; refresh(); BuffTap:UpdateNearbyWindow(); BuffTap:TrackNearby('nameplate2'); BuffTap.nearbySnapshot=nil; refresh(); assert(BuffTap.nearbyMotion.added>=1, BuffTap.nearbyMotion.added)")
test('Animated list glides rows that change place',setup+"BuffTap.db.nearbyAnimate=true; BuffTap.db.nearbyShowAll=true; BuffTap:TrackNearby('nameplate2'); refresh(); BuffTap:UpdateNearbyWindow(); local f=BuffTap.nearbyFrame; local g=f.rows[2].entry and f.rows[2].entry.guid; BuffTap.nearbyRowSlots[g]=1; BuffTap.nearbyRowSlots[f.rows[1].entry.guid]=nil; BuffTap:AnimateNearbyRows(f,5); assert(BuffTap.nearbyMotion.moved>=1); BuffTap.nearbyRowSlots[g]=4; BuffTap:AnimateNearbyRows(f,5); assert(BuffTap.nearbyMotion.moved==0,'upward moves snap')")
test('Scrolling and Reduce animation never animate',setup+"BuffTap.db.nearbyAnimate=true; BuffTap:TrackNearby('nameplate2'); refresh(); BuffTap:UpdateNearbyWindow(); local f=BuffTap.nearbyFrame; local g=f.rows[1].entry.guid; BuffTap.nearbyRowSlots[g]=3; BuffTap.nearbyRowSlotsOffset=1; BuffTap:AnimateNearbyRows(f,5); assert(BuffTap.nearbyMotion.moved==0); BuffTap.nearbyRowSlots[g]=3; BuffTap.db.optionsReduceMotion=true; BuffTap:AnimateNearbyRows(f,5); assert(BuffTap.nearbyMotion.moved==0)")
test('Customization has the Animated list switch',"local B=BuffTap; B:Options(); local f=B.options; assert(f.nearbyAnimate); f.nearbyAnimate:SetChecked(true); f.nearbyAnimate.scripts.OnClick(f.nearbyAnimate); assert(B.db.nearbyAnimate==true)")
test('Animated list turns on once for everyone, and off sticks',"local B=BuffTap; BuffTapDB={enabled=true,nearbyAnimate=false}; B:InitDB(); assert(B.db.nearbyAnimate==true); B.db.nearbyAnimate=false; B:InitDB(); assert(B.db.nearbyAnimate==false); BuffTapDB={}; B:InitDB(); assert(B.db.nearbyAnimate==true)")
